# Refactored BankAccount class

class BankAccount:
    INVALID_AMOUNT_ERROR = "Invalid amount"
    INSUFFICIENT_BALANCE_ERROR = "Insufficient balance."

    def __init__(self, balance=0):
        self._balance = balance

    @property
    def balance(self):
        """Encapsulated field access"""
        return self._balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            raise ValueError(self.INVALID_AMOUNT_ERROR)
        self._balance = value

    def _validate_amount(self, amount):
        """Extracted method for validating transaction amount"""
        if amount < 0:
            raise ValueError(self.INVALID_AMOUNT_ERROR)

    def deposit(self, amount):
        """Deposit money into the account"""
        self._validate_amount(amount)
        self._balance += amount
        return self.balance

    def withdraw(self, amount):
        """Withdraw money from the account"""
        self._validate_amount(amount)
        if amount > self.balance:
            raise ValueError(self.INSUFFICIENT_BALANCE_ERROR)
        self._balance -= amount
        return self.balance

    def view_balance(self):
        """Query for current balance"""
        return self.balance

    def transfer(self, other_account, amount):
        """Transfer funds to another account"""
        self.withdraw(amount)
        other_account.deposit(amount)
